"""Apply UI94 after the existing pinned UI93 build. Never touch project data."""
from __future__ import annotations
import base64,hashlib,json,sys,zlib
from pathlib import Path,PurePosixPath
PARENT_MANIFEST_SHA256='580d7f0d0c65c46d78029834e7014216d702862832429255df4dda35ea2f1849'
TARGET_VARIANT='workspace-ui94-quiet-header-anchored-profile-2026-10-04'
FILES={'app/static/app.js': {'before': 'c5adf2019e577e224b7cd5c217edc6f56438268dadbccc51b8937debe1395120', 'after': 'c0f5e6ac45b72b2f863f69e61fc0841dd46a5485fc2696a687173260d5877b39', 'bytes': 165562, 'payload': ''}, 'app/static/experience_shell.js': {'before': '9dc532466393a961c0112ae83460cc84dd3e575839489b995cf70a7cc45aefb7', 'after': 'e6c43cf7cf9860d488ad0640fd9859761bd87d2bdb03b09b76ea1f9a0fd51ae5', 'bytes': 12389, 'payload': ''}, 'app/static/fleet.html': {'before': 'c3c47e3c99b662b42f03037afac13eb6c90c4c50746e3189a99934b10f9f8a26', 'after': '354e103588d0ff996fd01db030a0fea9075b442bf44f7ac925293e0cde1c76d9', 'bytes': 6293, 'payload': ''}, 'app/static/index.html': {'before': '2729ddcfa9facc44bf6fc9ec2cc9d0241d4ce906449e9df4ea6e5c63bddaaebc', 'after': '1b8792aa0b01f823ec91889a4fe0c85bf3c9b2352271eaadcd2c33ca47dd1783', 'bytes': 24529, 'payload': ''}, 'app/static/sw.js': {'before': '72619b66dab855641675252eaafca4464c04fa49619174ae879e9451d33f1ecb', 'after': '190b6b304a49f54e9186ed9a13f22f69ee67b3d1afe9108b7c767c6b21906fe3', 'bytes': 12914, 'payload': ''}, 'app/static/visual_system_ui94.css': {'before': None, 'after': '260557281dfc9c724635f0b81ec02ac8b1f0565d50657bd12c9a61950dec72ab', 'bytes': 101077, 'payload': ''}, 'tests/browser_shell_ui94.py': {'before': None, 'after': 'd788e0ddb2991a8db15d657a1f1a20537b8149c5afe14ea97fc53da60e9cc7c2', 'bytes': 11059, 'payload': ''}, 'UI_PATCH.json': {'before': 'fb52d0b736d263e65279b1793ed9d8fd79b72e0ac8bda23a16fd0fc4e91e5af9', 'after': '7e800e30bdf9c189e702a5c8169ed3bc0f0ec2bd76db5620f1d9647b0bc37908', 'bytes': 2441, 'payload': ''}}

def apply(destination: Path) -> None:
    manifest_path=destination/'RELEASE_FILES.json'
    raw=manifest_path.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=PARENT_MANIFEST_SHA256:
        raise ValueError('UI94 requires the exact UI93 source manifest. Do not deploy.')
    manifest=json.loads(raw)
    for name,expected in manifest['files'].items():
        relative=PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise ValueError('Unsafe source manifest path.')
        path=destination.joinpath(*relative.parts)
        if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:
            raise ValueError('UI94 parent resource mismatch: '+name)
    prepared={}
    for name,record in FILES.items():
        path=destination/name
        if record['before'] is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('UI94 new resource already exists: '+name)
        elif manifest['files'].get(name)!=record['before']:
            raise ValueError('UI94 parent file mismatch: '+name)
        dec=zlib.decompressobj()
        data=dec.decompress(base64.b64decode(record['payload'],validate=True),record['bytes']+1)
        data+=dec.flush()
        if not dec.eof or dec.unused_data or dec.unconsumed_tail or len(data)!=record['bytes'] or hashlib.sha256(data).hexdigest()!=record['after']:
            raise ValueError('UI94 payload integrity failure: '+name)
        prepared[name]=data
    for name,data in prepared.items():
        path=destination/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
        manifest['files'][name]=FILES[name]['after']
    manifest['variant']=TARGET_VARIANT
    manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
    for name,expected in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('Derived UI94 integrity failure: '+name)

if __name__=='__main__':
    apply(Path(sys.argv[1]))
    print('Applied Workspace UI94: quiet header and account menu anchored to its button; approved art and UI93 email settings retained.')
